}

Method.Source:
 static JmgJobId getJmgJobIdFromProdId(ProdId _prodId)
 {
     ProdRouteJob prodRouteJob;

     select firstOnly JobId from prodRouteJob order by OprNum
         where prodRouteJob.ProdId == _prodId
             && prodRouteJob.OprPriority == RouteOprPriority::Primary;

     return prodRouteJob.JobId;
 }

